import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 94 · Christmas tips: keep a real Christmas tree fresh until New Year's

sc("""Sweetheart, every year, people spend eighty dollars on a beautiful real Christmas tree, and by the fifteenth of December, it's dropping needles all over the carpet, the branches are drooping, and it smells like nothing. By Christmas morning, it looks like it's been through a war. And it isn't the tree's fault. It's five little mistakes people make in the first hour after they bring it home.""",
   "dry Christmas tree dropping needles on carpet", "DEAD BY CHRISTMAS")
sc("""So tonight I'm giving you seven old-fashioned tricks that keep a real Christmas tree fresh, green and fragrant all the way to New Year's. And stay with me, because the last one is something my father did every single year, the minute the tree came through the door, and our trees still had soft needles in the middle of January.""",
   "fresh green Christmas tree in living room", "GREEN UNTIL JANUARY")

ch("Father's trees")
sc("""My father, Walter, cut our Christmas tree himself every year, from a farm out on Route Thirteen, where the farmer let him take one for a dollar if he helped with the fence posts. He'd drag it home on Danny's sled, through the snow, and the whole street could smell it coming. And that tree would stand in our front window until Twelfth Night, the sixth of January, still green.""",
   "father dragging Christmas tree on sled in snow 1950s", "A DOLLAR AND FENCE POSTS")
sc("""A cut tree is still alive for weeks, honey. It drinks water through its trunk, like flowers in a vase. A good-sized tree can drink a gallon a day in the first week. When it stops drinking, it starts dying. Every trick I'm going to tell you is about one thing. Keeping that tree drinking. In a minute I'll tell you the one mistake that stops it drinking in just a few hours.""",
   "Christmas tree stand full of water", "A GALLON A DAY")

ch("1. Choosing it")
sc("""Number one. Choose a fresh one. Grab a branch and pull your hand gently along it toward you. If more than a few needles come off in your hand, walk away. Bend a needle in half. On a fresh fir, it bends. On a dry one, it snaps. And lift the tree a few inches and drop it on its trunk. If green needles rain down, it was cut too long ago.""",
   "hand testing Christmas tree needles at lot", "THE NEEDLE TEST")
sc("""And pick the right kind, sweetheart. Fraser fir and noble fir hold their needles the longest, and they have strong branches for heavy ornaments. Balsam fir smells the best, like a Christmas card. Scotch pine is cheapest and holds on well, but it's prickly. Spruce smells wonderful but drops its needles the fastest. My father always bought balsam, for the smell.""",
   "different types of Christmas trees at lot", "PICK THE RIGHT KIND")

sc("""And here's a little secret, sweetheart. The trees at the big box stores were usually cut in early November and trucked across the country, sitting in a hot trailer. A tree from a local farm, where you cut it yourself or they cut it that week, will last twice as long. It costs about the same. And you get a hayride and a cup of cocoa thrown in. My grandchildren wouldn't have it any other way.""",
   "family cutting tree at Christmas tree farm", "BUY IT LOCAL")
ch("2. The fresh cut")
sc("""Number two, the most important mistake of all. Not cutting the trunk. When a tree is cut, the sap seals over the stump within a few hours, like a scab. Then it can't drink a drop, no matter how much water you give it. So right before you put it in the stand, cut a fresh slice off the bottom, about an inch thick, straight across. Most tree lots will do it for free if you ask.""",
   "sawing fresh slice off Christmas tree trunk", "CUT AN INCH OFF")
sc("""And get it into water within a few hours of that cut, honey. If you can't put it up right away, stand it in a bucket of water in the garage or on a cold porch. And cut straight across, not at an angle and not in a point. A flat cut sits in the water evenly. And don't drill holes in the trunk either. The old wives' tales are wrong about that.""",
   "Christmas tree in bucket of water on porch", "STRAIGHT ACROSS")

ch("3. The stand")
sc("""Number three. A stand that's too small. If the stand only holds a cup of water, your tree will drink it dry in a few hours, the sap will seal over, and it's finished. Get a stand that holds at least a gallon. The rule is a quart of water for every inch across the trunk. A four-inch trunk needs a gallon. My father used an old galvanized wash tub filled with rocks.""",
   "large Christmas tree stand galvanized tub", "A GALLON STAND")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. And check the water every single day, especially the first week. Stick your finger in. If the water drops below the bottom of the trunk even once, the stump can seal over, and you'll have to start all over. I keep a watering can right behind the tree all December.""",
   "watering can behind Christmas tree", "CHECK IT EVERY DAY")

sc("""Here's a trick for checking the water without crawling under the tree on your hands and knees, honey. Put a long funnel with a piece of plastic tubing right behind the trunk, tucked in the branches, going down into the stand. You can pour water down it standing up. My son-in-law rigged one up for me when my knees got bad, and I've used it for fifteen years.""",
   "funnel and tubing to water Christmas tree", "NO MORE CRAWLING")
ch("4. Plain water")
sc("""Number four. Putting things in the water. People add aspirin, sugar, soda pop, bleach, even vodka. I've heard them all. The Christmas tree growers and the agricultural colleges have tested every one of them. Plain tap water works as well as anything, and better than most. Sugar just grows mold. Save the aspirin for your headache, honey. Plain, cool water. That's all.""",
   "pouring plain water into tree stand", "PLAIN WATER")

ch("5. The heat")
sc("""So far, a fresh tree, a fresh cut, a big stand, and plain water. Number five. Putting the tree next to the heat. Not by the fireplace, not next to a heating vent, not by a sunny window. Heat dries a tree out twice as fast. Put it in the coolest corner of the room you can, and if you have a vent nearby, close it or put a deflector on it. Turn the heat down a little at night.""",
   "Christmas tree away from fireplace and heater", "AWAY FROM THE HEAT")
sc("""And this is a safety rule, too, sweetheart. A dry Christmas tree catches fire in seconds. It goes up like a torch. Use LED lights, which stay cool, and turn the tree lights off when you go to bed or leave the house. Never put candles on or near the tree. My mother's friend lost her house in nineteen sixty-four to an old string of lights on a dry tree.""",
   "LED Christmas lights on tree", "LIGHTS OFF AT NIGHT")

sc("""And put a waterproof tray or a plastic boot mat under your tree stand before the tree skirt goes on. A stand always leaks a little, and a full gallon spilled under a tree can ruin a wood floor or a carpet. One year, Harold knocked the stand while adjusting the lights, and the water ran all the way under the couch. We found the puddle on New Year's Day.""",
   "plastic tray under Christmas tree stand", "PROTECT YOUR FLOOR")
ch("6. The mist")
sc("""Number six. A little drink for the branches. Fill a spray bottle with water, and once or twice a week, mist the branches, the outside ones especially, before you turn the lights on. Never spray it while the lights are on or plugged in. It keeps the needles from drying out, and it brings the smell right back. My mother did it every Sunday morning before church.""",
   "spray bottle misting Christmas tree branches", "A SUNDAY MIST")

ch("7. Father's first hour")
sc("""And number seven, the one I promised you. My father's first hour. When he brought the tree home, before it ever came inside the house, he cut a fresh inch off the trunk and stood it in a bucket of lukewarm water in the cold shed overnight. He swore lukewarm water got it drinking faster. The tree experts say any water works, honey, but I still do it his way. And a night in the cold lets the tree rest before it meets the heat inside.""",
   "Christmas tree in bucket in cold shed night", "A NIGHT IN THE SHED")
sc("""Then the next morning, he cut another thin slice off the bottom, put it straight into the stand, and filled it with lukewarm water. That tree would drink almost two gallons the first day. We had to refill it at breakfast, lunch and supper. And it never dropped a needle until January. People on Elm Street used to ask him his secret. He'd just say, give it a drink, same as you would a tired man.""",
   "man pouring water into tree stand morning", "GIVE IT A DRINK")

sc("""And when the season's over, don't just drag it to the curb, sweetheart. Many towns collect trees and grind them into mulch for the parks. Or put it in your backyard, and the birds will use it for shelter all winter. My father stood ours up in the snow by the bird feeder every January, and hung pinecones dipped in peanut butter on its branches. The cardinals loved it.""",
   "old Christmas tree in snowy backyard with birds", "A HOME FOR THE BIRDS")
ch("Grandma's tree")
sc("""So one more time. Choose a fresh tree with the needle test. Cut an inch off the trunk, straight across. Use a big stand, a gallon or more, and check it every day. Plain water. Keep it away from the heat, and turn the lights off at night. Mist the branches. And give it a night in a bucket of lukewarm water before it comes inside. Green until New Year's, sweetheart. I promise.""",
   "beautiful green Christmas tree lit at night", "GREEN UNTIL NEW YEAR'S")
sc("""Tell me in the comments, honey. Real tree or artificial in your house? And did your father have a secret too? The whole playlist of Grandma's Christmas tips is right there on your screen, and I'll see you in the next video. Good night, sweetheart.""",
   "cozy living room Christmas tree evening", "REAL OR ARTIFICIAL?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma94", "7 Mistakes That Kill Your Christmas Tree Before CHRISTMAS",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Tree care guidance consistent with the National Christmas Tree Association and university extension services: fresh cut, at least 1 quart of water per inch of trunk diameter, plain water, away from heat.",
      "Fire safety: dry Christmas trees ignite rapidly (NFPA, U.S. Fire Administration)."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
